mapper.select:
SELECT /* CodeMapper.selectCodeGroupList 코드그룹 목록 */ GRP_CMM_CD , GRP_CMM_CD_NM , GRP_CMM_CD_DESC , SYSTEM_GUBUN , SORT_NO FROM TBCM_COMMON_CODE_GROUP WHERE MB_ID = #{mbId}
AND (GRP_CMM_CD LIKE CONCAT('%', #{keyword}, '%') OR GRP_CMM_CD_NM LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY SORT_NO, GRP_CMM_CD

SELECT /* CodeMapper.countCodeGroup 그룹코드 중복 확인 */
       COUNT(*)
  FROM TBCM_COMMON_CODE_GROUP
 WHERE MB_ID = #{mbId}
   AND GRP_CMM_CD = #{grpCmmCd}

mapper.update:
UPDATE TBCM_COMMON_CODE_GROUP /* CodeMapper.updateCodeGroup */
   SET GRP_CMM_CD_NM   = #{g.grpCmmCdNm}
     , GRP_CMM_CD_DESC = #{g.grpCmmCdDesc}
     , SYSTEM_GUBUN    = #{g.systemGubun}
     , SORT_NO         = IFNULL(#{g.sortNo}, 0)
     , UP_EMP_CD       = #{userId}
     , UP_DTM          = NOW()
 WHERE MB_ID = #{mbId}
   AND GRP_CMM_CD = #{g.grpCmmCd}

mapper.delete:
DELETE FROM TBCM_COMMON_CODE_GROUP /* CodeMapper.deleteCodeGroup */
 WHERE MB_ID = #{mbId}
   AND GRP_CMM_CD = #{grpCmmCd}

mapper.select:
SELECT /* CodeMapper.selectCodeList 코드 목록 */ GRP_CMM_CD , CD_VL , CD_VL_NM , USE_YN , SORT_NO FROM TBCM_COMMON_CODE WHERE MB_ID = #{mbId} AND GRP_CMM_CD = #{grpCmmCd}
AND USE_YN = #{useYn}
ORDER BY SORT_NO, CD_VL

SELECT /* CodeMapper.countCode 코드값 중복 확인 */
       COUNT(*)
  FROM TBCM_COMMON_CODE
 WHERE MB_ID = #{mbId}
   AND GRP_CMM_CD = #{grpCmmCd}
   AND CD_VL = #{cdVl}

mapper.update:
UPDATE TBCM_COMMON_CODE /* CodeMapper.updateCode */
   SET CD_VL_NM  = #{c.cdVlNm}
     , USE_YN    = IFNULL(NULLIF(#{c.useYn}, ''), 'Y')
     , SORT_NO   = IFNULL(#{c.sortNo}, 0)
     , UP_EMP_CD = #{userId}
     , UP_DTM    = NOW()
 WHERE MB_ID = #{mbId}
   AND GRP_CMM_CD = #{c.grpCmmCd}
   AND CD_VL = #{c.cdVl}

mapper.delete:
DELETE FROM TBCM_COMMON_CODE /* CodeMapper.deleteCode */
 WHERE MB_ID = #{mbId}
   AND GRP_CMM_CD = #{grpCmmCd}
   AND CD_VL = #{cdVl}

DELETE FROM TBCM_COMMON_CODE /* CodeMapper.deleteCodeByGroup 그룹 삭제 때 아래 코드 전부 */
 WHERE MB_ID = #{mbId}
   AND GRP_CMM_CD = #{grpCmmCd}
